/**
 * Shared rules for the two transaction identifiers.
 *
 * Both backends produce the same shapes: TRX_ID is a 12-digit decimal string
 * (the business primary key), and IDEMPOTENCY_KEY is the opaque token that
 * identifies one original payment request. The Db2 bridge applies these same
 * rules in Java, so a value generated by either tier is valid in both.
 */
import { randomUUID } from "node:crypto";

/** Exactly 12 numeric digits, e.g. "200000000001". */
export const TRX_ID_PATTERN = /^[0-9]{12}$/;

/** Opaque request token, 1-36 chars, safe to store in CHAR(36). */
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9._:-]{1,36}$/;

export function isValidTrxId(value: unknown): value is string {
  return typeof value === "string" && TRX_ID_PATTERN.test(value);
}

export function assertTrxId(value: unknown): string {
  if (!isValidTrxId(value)) {
    throw new Error(`Database returned an invalid 12-digit TRX_ID: ${String(value)}`);
  }
  return value;
}

/**
 * Only accept a client-supplied key when it is a well-formed opaque token.
 * Anything missing, too long, or unusual gets a fresh UUID, so a malformed
 * value can never be used to replay somebody else's payment.
 */
export function normalizeIdempotencyKey(value: unknown): string {
  if (typeof value === "string" && IDEMPOTENCY_KEY_PATTERN.test(value)) {
    return value;
  }
  return randomUUID();
}
